from datetime import datetime, time
from typing import Dict, Set


class Notifier:
    CHANNELS = ("email", "sms", "push")

    def __init__(self, quiet_start: time = time(22, 0), quiet_end: time = time(7, 0)) -> None:
        self.quiet_start = quiet_start
        self.quiet_end = quiet_end
        self.users: Dict[str, Dict[str, bool]] = {}

    def add_user(self, user: str) -> None:
        """Add a new user with default preferences (email enabled, sms/push disabled)."""
        self.users[user] = {
            "email": True,
            "sms": False,
            "push": False,
        }

    def set_channel(self, user: str, channel: str, enabled: bool) -> None:
        """Configure delivery preference for a given channel."""
        if channel not in self.CHANNELS:
            raise ValueError(f"Invalid channel '{channel}'. Allowed channels are: {self.CHANNELS}")
        if user not in self.users:
            self.add_user(user)
        self.users[user][channel] = enabled

    def _is_quiet_hour(self, current_time: time) -> bool:
        """Check if the given time falls within the quiet hours range."""
        if self.quiet_start <= self.quiet_end:
            return self.quiet_start <= current_time < self.quiet_end
        else:
            # Overnights quiet hours (e.g., 22:00 to 07:00)
            return current_time >= self.quiet_start or current_time < self.quiet_end

    def send(self, user: str, message: str, at: datetime) -> list[str]:
        """Send a message; returns the channels it was delivered to, in CHANNELS order."""
        if user not in self.users:
            self.add_user(user)

        user_prefs = self.users[user]
        in_quiet_hours = self._is_quiet_hour(at.time())
        delivered_channels: list[str] = []

        for channel in self.CHANNELS:
            if not user_prefs.get(channel, False):
                continue

            # Email is exempt from quiet hours; sms and push are muted
            if in_quiet_hours and channel in ("sms", "push"):
                continue

            delivered_channels.append(channel)

        return delivered_channels
